examples.code:
try:
    value = int('abc')
except ValueError as exc:
    print('bad input:', exc)

try:
    n = int('42')
except ValueError:
    print('bad')
else:
    print('parsed', n)

try:
    raise RuntimeError('boom')
except RuntimeError:
    print('handled')
finally:
    print('cleanup')

try:
    try:
        int('x')
    except ValueError as exc:
        raise RuntimeError('config invalid') from exc
except RuntimeError as exc:
    print(exc, '| caused by', type(exc.__cause__).__name__)
